{"earlier_TRAIN_examples":[{"example_hash":"fec7b5825780bd0577ccc3f343b3ab9cff60e04e167048e9484eb2f764e82c3d","units":[{"id":"s0","role":"rule","view":null,"text":"§7703. Determination of marital status"},{"id":"s1","role":"rule","view":null,"text":"(a) General rule"},{"id":"s2","role":"rule","view":null,"text":"    (1) the determination of whether an individual is married shall be made as of the close of his taxable year; except that if his spouse dies during his taxable year such determination shall be made as of the time of such death; and"},{"id":"s3","role":"rule","view":null,"text":"    (2) an individual legally separated from his spouse under a decree of divorce or of separate maintenance shall not be considered as married."},{"id":"s4","role":"rule","view":null,"text":"(b) Certain married individuals living apart"},{"id":"s5","role":"rule","view":null,"text":"For purposes of those provisions of this title which refer to this subsection, if-"},{"id":"s6","role":"rule","view":null,"text":"    (1) an individual who is married (within the meaning of subsection (a)) and who files a separate return maintains as his home a household which constitutes for more than one-half of the taxable year the principal place of abode of a child with respect to whom such individual is entitled to a deduction for the taxable year under section 151,"},{"id":"s7","role":"rule","view":null,"text":"    (2) such individual furnishes over one-half of the cost of maintaining such household during the taxable year, and"},{"id":"s8","role":"rule","view":null,"text":"    (3) during the last 6 months of the taxable year, such individual's spouse is not a member of such household,"},{"id":"s9","role":"rule","view":null,"text":"such individual shall not be considered as married."},{"id":"s10","role":"fact","view":null,"text":"Alice and Bob got married on April 5th, 2012. Alice and Bob were legally separated under a decree of divorce on September 16th, 2017."},{"id":"s11","role":"query","view":null,"text":"Section 7703(a)(2) applies to Alice for the year 2018."}],"code":"v_separation_year = 2017 # s10
v_query_year = 2018 # s11
v_close_of_year = 'the close of his taxable year' # s2
v_time_of_death = 'the time of such death' # s2
b_spouse_dies_during_taxable_year = observation('Alice', 's10', 'his spouse dies during his taxable year', 's2')
b_legally_separated = observation('Alice', 's10', 'legally separated from his spouse under a decree of divorce or of separate maintenance', 's3')
b_individual_is_married = observation('Alice', 's10', 'individual who is married', 's6')
b_files_separate_return = observation('Alice', 's10', 'files a separate return', 's6')
b_maintains_home_household = observation('Alice', 's10', 'maintains as his home a household', 's6')
b_principal_abode_of_child = observation('Alice', 's10', 'the principal place of abode of a child', 's6')
b_furnishes_household_cost = observation('Alice', 's10', 'such individual furnishes', 's7')
b_spouse_not_household_member = observation('Alice', 's10', "such individual's spouse is not a member of such household", 's8')
b_subsection_reference_applies = residual('s5', 'those provisions of this title which refer to this subsection')
b_more_than_half_year = residual('s6', 'more than one-half of the taxable year')
b_section_151_deduction = residual('s6', 'entitled to a deduction for the taxable year under section 151')
b_over_half_cost = residual('s7', 'over one-half of the cost of maintaining such household during the taxable year')
b_last_six_months = residual('s8', 'during the last 6 months of the taxable year')
n_a2_condition = (b_legally_separated and lt(v_separation_year, v_query_year))
n_b_condition_1 = (b_individual_is_married and (not c_a2_applies) and b_files_separate_return and b_maintains_home_household and b_principal_abode_of_child and b_more_than_half_year and b_section_151_deduction)
n_b_condition_2 = (b_furnishes_household_cost and b_over_half_cost)
n_b_condition_3 = (b_last_six_months and b_spouse_not_household_member)
n_b_conditions = (n_b_condition_1 and n_b_condition_2 and n_b_condition_3)
@scope('s0')
def sc_section_7703():
    return True
@scope('s1')
def sc_general_rule():
    return True
@scope('s4')
def sc_living_apart():
    return True
@scope('s5')
def sc_referenced_provisions():
    return b_subsection_reference_applies
@rule('s2', otherwise=None)
def c_determination_policy():
    return object(pair('taxable_year', v_query_year), pair('determination_point', (v_time_of_death if b_spouse_dies_during_taxable_year else v_close_of_year)))
@rule('s3', otherwise=False)
def c_a2_applies():
    return n_a2_condition
@rule('s6', 's7', 's8', 's9', otherwise=False)
def c_b_not_considered_married():
    return n_b_conditions
query = ('Entailment' if c_a2_applies else 'Contradiction')
"}],"CURRENT":{"dataset":"SARA_v2_Binary","units":[{"id":"s0","role":"rule","view":null,"text":"§3306. Definitions","context":[]},{"id":"s1","role":"rule","view":null,"text":"(a) Employer","context":["s0"]},{"id":"s2","role":"rule","view":null,"text":"    (1) In general","context":["s1"]},{"id":"s3","role":"rule","view":null,"text":"    The term "employer" means, with respect to any calendar year, any person who-","context":["s2"]},{"id":"s4","role":"rule","view":null,"text":"        (A) during the calendar year or the preceding calendar year paid wages of $1,500 or more, or","context":["s3"]},{"id":"s5","role":"rule","view":null,"text":"        (B) on each of some 10 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least one individual in employment for some portion of the day.","context":["s3"]},{"id":"s6","role":"rule","view":null,"text":"    For purposes of this paragraph, there shall not be taken into account any wages paid to, or employment of, an employee performing domestic services referred to in paragraph (3).","context":["s5"]},{"id":"s7","role":"rule","view":null,"text":"    (2) Agricultural labor","context":["s1"]},{"id":"s8","role":"rule","view":null,"text":"    In the case of agricultural labor, the term "employer" means, with respect to any calendar year, any person who-","context":["s7"]},{"id":"s9","role":"rule","view":null,"text":"        (A) during the calendar year or the preceding calendar year paid wages of $20,000 or more for agricultural labor, or","context":["s8"]},{"id":"s10","role":"rule","view":null,"text":"        (B) on each of some 10 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least 5 individuals in employment in agricultural labor for some portion of the day.","context":["s8"]},{"id":"s11","role":"rule","view":null,"text":"    (3) Domestic service","context":["s1"]},{"id":"s12","role":"rule","view":null,"text":"    In the case of domestic service in a private home, local college club, or local chapter of a college fraternity or sorority, the term "employer" means, with respect to any calendar year, any person who during the calendar year or the preceding calendar year paid wages in cash of $1,000 or more for such service.","context":["s11"]},{"id":"s13","role":"rule","view":null,"text":"    (4) Special rule","context":["s1"]},{"id":"s14","role":"rule","view":null,"text":"    A person treated as an employer under paragraph (3) shall not be treated as an employer with respect to wages paid for any service other than domestic service referred to in paragraph (3) unless such person is treated as an employer under paragraph (1) or (2) with respect to such other service.","context":["s13"]},{"id":"s15","role":"rule","view":null,"text":"(b) Wages","context":["s0"]},{"id":"s16","role":"rule","view":null,"text":"For purposes of this chapter, the term "wages" means all remuneration for employment, including the cash value of all remuneration (including benefits) paid in any medium other than cash; except that such term shall not include-","context":["s15"]},{"id":"s17","role":"rule","view":null,"text":"    (1) that part of the remuneration which, after remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) equal to $7,000 with respect to employment has been paid to an individual by an employer during any calendar year, is paid to such individual by such employer during such calendar year;","context":["s16"]},{"id":"s18","role":"rule","view":null,"text":"    (2) the amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of-","context":["s16"]},{"id":"s19","role":"rule","view":null,"text":"        (A) sickness or accident disability, or","context":["s18"]},{"id":"s20","role":"rule","view":null,"text":"        (C) death;","context":["s18"]},{"id":"s21","role":"rule","view":null,"text":"    (7) remuneration paid in any medium other than cash to an employee for service not in the course of the employer's trade or business;","context":["s16"]},{"id":"s22","role":"rule","view":null,"text":"    (10) any payment or series of payments by an employer to an employee or any of his dependents which is paid-","context":["s16"]},{"id":"s23","role":"rule","view":null,"text":"        (A) upon or after the termination of an employee's employment relationship because of (i) death, or (ii) retirement for disability, and","context":["s22"]},{"id":"s24","role":"rule","view":null,"text":"        (B) under a plan established by the employer which makes provision for his employees generally or a class or classes of his employees (or for such employees or class or classes of employees and their dependents),","context":["s22"]},{"id":"s25","role":"rule","view":null,"text":"    other than any such payment or series of payments which would have been paid if the employee's employment relationship had not been so terminated;","context":["s24"]},{"id":"s26","role":"rule","view":null,"text":"    (11) remuneration for agricultural labor paid in any medium other than cash;","context":["s16"]},{"id":"s27","role":"rule","view":null,"text":"    (15) any payment made by an employer to a survivor or the estate of a former employee after the calendar year in which such employee died;","context":["s16"]},{"id":"s28","role":"rule","view":null,"text":"(c) Employment","context":["s0"]},{"id":"s29","role":"rule","view":null,"text":"For purposes of this chapter, the term "employment" means any service, of whatever nature,","context":["s28"]},{"id":"s30","role":"rule","view":null,"text":"    (A) performed by an employee for the person employing him, irrespective of the citizenship or residence of either, within the United States, and","context":["s29"]},{"id":"s31","role":"rule","view":null,"text":"    (B) performed outside the United States (except in a contiguous country with which the United States has an agreement relating to unemployment compensation) by a citizen of the United States as an employee of an American employer, except-","context":["s29"]},{"id":"s32","role":"rule","view":null,"text":"    (1) agricultural labor unless-","context":["s29"]},{"id":"s33","role":"rule","view":null,"text":"        (A) such labor is performed for a person who-","context":["s32"]},{"id":"s34","role":"rule","view":null,"text":"            (i) during the calendar year or the preceding calendar year paid remuneration in cash of $20,000 or more to individuals employed in agricultural labor (including labor performed by an alien referred to in subparagraph (B)), or","context":["s33"]},{"id":"s35","role":"rule","view":null,"text":"            (ii) on each of some 10 days during the calendar year or the preceding calendar year, each day being in a different calendar week, employed in agricultural labor (including labor performed by an alien referred to in subparagraph (B)) for some portion of the day (whether or not at the same moment of time) 5 or more individuals; and","context":["s33"]},{"id":"s36","role":"rule","view":null,"text":"        (B) such labor is not agricultural labor performed by an individual who is an alien admitted to the United States to perform agricultural labor pursuant to sections 214(c) and 101(a)(15)(H) of the Immigration and Nationality Act.","context":["s32"]},{"id":"s37","role":"rule","view":null,"text":"    (2) domestic service in a private home, local college club, or local chapter of a college fraternity or sorority unless performed for a person who paid cash remuneration of $1,000 or more to individuals employed in such domestic service in the calendar year or the preceding calendar year;","context":["s29"]},{"id":"s38","role":"rule","view":null,"text":"    (5) ","context":["s29"]},{"id":"s39","role":"rule","view":null,"text":"        (A) service performed by an individual in the employ of his son, daughter, or spouse;","context":["s38"]},{"id":"s40","role":"rule","view":null,"text":"        (B) service performed by a child under the age of 21 in the employ of his father or mother;","context":["s38"]},{"id":"s41","role":"rule","view":null,"text":"    (6) service performed in the employ of the United States Government","context":["s29"]},{"id":"s42","role":"rule","view":null,"text":"    (7) service performed in the employ of a State, or any political subdivision thereof.","context":["s29"]},{"id":"s43","role":"rule","view":null,"text":"    (10)","context":["s29"]},{"id":"s44","role":"rule","view":null,"text":"        (A) service performed in the employ of a school, college, or university, if such service is performed","context":["s43"]},{"id":"s45","role":"rule","view":null,"text":"            (i) by a student who is enrolled and is regularly attending classes at such school, college, or university, or","context":["s44"]},{"id":"s46","role":"rule","view":null,"text":"            (ii) by the spouse of such a student, or","context":["s44"]},{"id":"s47","role":"rule","view":null,"text":"        (B) service performed in the employ of a hospital, if such service is performed by a patient of such hospital;","context":["s43"]},{"id":"s48","role":"rule","view":null,"text":"    (11) service performed in the employ of a foreign government (including service as a consular or other officer or employee or a nondiplomatic representative);","context":["s29"]},{"id":"s49","role":"rule","view":null,"text":"    (13) service performed as a student nurse in the employ of a hospital or a nurses' training school by an individual who is enrolled and is regularly attending classes in a nurses' training school;","context":["s29"]},{"id":"s50","role":"rule","view":null,"text":"    (16) service performed in the employ of an international organization;","context":["s29"]},{"id":"s51","role":"rule","view":null,"text":"    (21) service performed by a person committed to a penal institution.","context":["s29"]},{"id":"s52","role":"fact","view":null,"text":"Alice has paid wages of $3200 to Bob for domestic service done in her home from Feb 1st, 2017 to Sep 2nd, 2017, in Baltimore, Maryland, USA.","context":[]},{"id":"s53","role":"query","view":null,"text":"Section 3306(c)(2) applies to Alice employing Bob for the year 2017.","context":[]}],"required_scope_sources":["s32"],"native_output_schema":{"type":"string","enum":["Contradiction","Entailment"]}},"source_only_feedback":{"error":"Only a structural title can have a literal unconditional scope","diagnostics":null,"source_validation":{"issues":[],"source_only":true,"grading_information_used":false,"candidate_modified":false,"instruction":"Return a complete fresh candidate grounded in the public source. Preserve unknowns; do not coerce numbers to truth, invent missing rules, or substitute paragraph IDs for legal conclusions."}}}
